<script setup lang="ts">
import { toRefs } from 'vue'
import type { LiveSoloSettingsState } from '~/features/live-solo/useLiveSoloSettings'
const props = defineProps<{ state: LiveSoloSettingsState }>()
const { draft, loading, busy, dirty, writable, hasMatches, error, saved, formatOptions, laneOptions, sections, load, number, format,
  addStage, removeStage, stageNumber, stageLane, enabled, recording, opponents, save, back, leaveOpen, setLeave, leave } = toRefs(props.state)
</script>
<template>
  <div data-contained-workspace-page class="flex h-full min-h-0 flex-col gap-4 px-4 pb-6 pt-3 md:px-8">
    <header class="flex flex-wrap items-center gap-3"><Button variant="ghost" @click="back">{{ $t('liveSolo.back') }}</Button><h1 class="text-display text-2xl">{{ $t('liveSolo.settings.title') }}</h1><Badge v-if="!writable" variant="secondary">{{ $t('liveSolo.settings.readOnly') }}</Badge><Button class="ml-auto" variant="ghost" :disabled="busy || dirty" @click="load">{{ $t('common.label.refresh') }}</Button></header>
    <Alert v-if="error" variant="destructive"><AlertDescription>{{ $message(error) }}</AlertDescription></Alert>
    <Alert v-if="saved"><AlertDescription>{{ $t('liveSolo.settings.saved') }}</AlertDescription></Alert>
    <Card class="min-h-0 flex-1"><ScrollSurface axis="y" class="h-full" :aria-label="$t('liveSolo.settings.title')"><CardContent class="py-5">
      <Skeleton v-if="loading && !draft" class="h-64" />
      <UiForm v-else-if="draft" validation="feature" class="flex flex-col gap-5" @submit="save">
        <Field orientation="horizontal"><Checkbox id="live-solo-enabled" :model-value="draft.enabled" :disabled="!writable || busy" @update:model-value="enabled" /><FieldLabel for="live-solo-enabled">{{ $t('liveSolo.settings.enabled') }}</FieldLabel></Field>
        <p class="text-sm text-muted-foreground">{{ $t('liveSolo.settings.snapshot') }}</p>
        <DefinitionSection v-for="section in sections" :key="section.key" :title="$t(section.title)" :collapsible="false"><FieldGroup class="grid gap-4 sm:grid-cols-2 lg:grid-cols-3">
          <Field v-if="section.key === 'match'"><FieldLabel for="live-solo-format">{{ $t('liveSolo.settings.format') }}</FieldLabel><Select :model-value="draft.bracketFormat" :disabled="!writable || busy || hasMatches" @update:model-value="format"><SelectTrigger id="live-solo-format"><SelectValue /></SelectTrigger><SelectContent><SelectItem v-for="item in formatOptions" :key="item.value" :value="item.value">{{ $t(item.key) }}</SelectItem></SelectContent></Select><FieldDescription v-if="hasMatches">{{ $t('liveSolo.settings.formatLocked') }}</FieldDescription></Field>
          <Field v-for="field in section.fields" :key="field.key"><FieldLabel :for="field.key">{{ $t(field.label) }}</FieldLabel><NumberInput :id="field.key" :model-value="draft[field.key]" :min="field.min" :max="field.max" :disabled="!writable || busy" @update:model-value="number(field.key, $event)" /></Field>
          <template v-if="section.key === 'media'"><Field orientation="horizontal"><Checkbox id="live-solo-opponents" :model-value="draft.participantsMayViewOpponents" :disabled="!writable || busy" @update:model-value="opponents" /><FieldLabel for="live-solo-opponents">{{ $t('liveSolo.settings.opponents') }}</FieldLabel></Field><Field orientation="horizontal"><Checkbox id="live-solo-recording" :model-value="draft.recordingEnabled" :disabled="!writable || busy" @update:model-value="recording" /><FieldLabel for="live-solo-recording">{{ $t('liveSolo.settings.recording') }}</FieldLabel></Field></template>
        </FieldGroup></DefinitionSection>
        <Separator /><DefinitionSection :title="$t('liveSolo.settings.stages')" :collapsible="false"><div class="flex flex-col gap-4"><div v-for="(row,index) in draft.stageRules" :key="index" class="grid items-end gap-3 sm:grid-cols-[1fr_1fr_1fr_auto]"><Field><FieldLabel :for="'stage-lane-' + index">{{ $t('liveSolo.settings.lane') }}</FieldLabel><Select :model-value="row.lane" :disabled="!writable || busy" @update:model-value="stageLane(index,$event)"><SelectTrigger :id="'stage-lane-' + index"><SelectValue /></SelectTrigger><SelectContent><SelectItem v-for="item in laneOptions" :key="item.value" :value="item.value">{{ $t(item.key) }}</SelectItem></SelectContent></Select></Field><Field><FieldLabel :for="'stage-number-' + index">{{ $t('liveSolo.settings.stage') }}</FieldLabel><NumberInput :id="'stage-number-' + index" :model-value="row.stage" :min="1" :disabled="!writable || busy" @update:model-value="stageNumber(index,'stage',$event)" /></Field><Field><FieldLabel :for="'stage-wins-' + index">{{ $t('liveSolo.settings.stageWins') }}</FieldLabel><NumberInput :id="'stage-wins-' + index" :model-value="row.requiredWins" :min="1" :max="1024" :disabled="!writable || busy" @update:model-value="stageNumber(index,'requiredWins',$event)" /></Field><Button v-if="writable" type="button" variant="ghost" :disabled="busy" @click="removeStage(index)">{{ $t('liveSolo.settings.remove') }}</Button></div><div><Button v-if="writable" type="button" variant="outline" :disabled="busy" @click="addStage">{{ $t('liveSolo.settings.addStage') }}</Button></div></div></DefinitionSection>
        <div v-if="writable" class="flex justify-end gap-3"><Badge v-if="dirty" variant="secondary">{{ $t('liveSolo.settings.unsaved') }}</Badge><Button type="submit" :disabled="busy || !dirty">{{ $t('liveSolo.settings.save') }}</Button></div>
      </UiForm>
    </CardContent></ScrollSurface></Card>
    <AlertDialog :open="leaveOpen" @update:open="setLeave"><AlertDialogContent><AlertDialogHeader><AlertDialogTitle>{{ $t('liveSolo.settings.unsavedTitle') }}</AlertDialogTitle><AlertDialogDescription>{{ $t('liveSolo.settings.unsavedDescription') }}</AlertDialogDescription></AlertDialogHeader><AlertDialogFooter><AlertDialogCancel>{{ $t('common.action.cancel') }}</AlertDialogCancel><Button @click="leave">{{ $t('liveSolo.settings.discard') }}</Button></AlertDialogFooter></AlertDialogContent></AlertDialog>
  </div>
</template>
